#include <iostream>
#include <cmath>

int main() {
    // Parse seconds from input: 500
    int totalSeconds = 0;
    if (std::cin >> totalSeconds) {
        int minutes = totalSeconds / 60;
        int remainingSeconds = totalSeconds % 60;
        std::cout << totalSeconds << " seconds is " << minutes 
                  << " minutes and " << remainingSeconds << " seconds" << std::endl;
    }

    // Demonstrate octal, hex, and scientific literals
    int hexVal = 0xFFFF;
    int octVal = 010;
    double sciVal = 1.23456E2;
    std::cout << "Hex 0xFFFF: " << hexVal << ", Oct 010: " << octVal << std::endl;
    std::cout << "Scientific 1.23456E2: " << sciVal << std::endl;

    // Exponentiation
    std::cout << "pow(2.0, 3): " << std::pow(2.0, 3) << std::endl;

    return 0;
}
